div.script:
                    (function () {
                        var typeEl = document.getElementById('time_off_type');
                        var fromEl = document.getElementById('date_from');
                        var toEl = document.getElementById('date_to');
                        var daysEl = document.getElementById('requested_days');
                        var fromLabel = document.getElementById('date_from_label');
                        var toGroup = document.getElementById('date_to_group');
                        var unitOptions = document.getElementById('unit_options');
                        var customHoursWrap = document.getElementById('custom_hours_wrap');
                        var halfEl = document.getElementById('half_day');
                        var hoursEl = document.getElementById('custom_hours');
                        var periodWrap = document.getElementById('half_day_period_wrap');
                        var periodEl = document.getElementById('half_day_period');
                        var hoursWrap = document.getElementById('hours_wrap');
                        var hourFromEl = document.getElementById('hour_from');
                        var hourToEl = document.getElementById('hour_to');
                        var supportGroup = document.getElementById('support_document_group');
                        var supportEl = document.getElementById('supporting_documents');
                        var supportList = document.getElementById('support_files_list');
                        var selectedFiles = [];

                        // Put the kept files back into the file input so they are submitted.
                        function syncFiles() {
                            var transfer = new DataTransfer();
                            selectedFiles.forEach(function (file) { transfer.items.add(file); });
                            supportEl.files = transfer.files;
                        }

                        // Show the chosen files, each with a remove (x) button on hover.
                        function renderFiles() {
                            supportList.textContent = '';
                            selectedFiles.forEach(function (file, index) {
                                var item = document.createElement('div');
                                item.className = 'o_support_file d-flex align-items-center border rounded px-2 py-1';
                                var name = document.createElement('span');
                                name.textContent = file.name;
                                var remove = document.createElement('button');
                                remove.type = 'button';
                                remove.className = 'btn-close ms-2';
                                remove.title = 'Remove';
                                remove.setAttribute('aria-label', 'Remove');
                                remove.addEventListener('click', function () {
                                    selectedFiles.splice(index, 1);
                                    syncFiles();
                                    renderFiles();
                                });
                                item.appendChild(name);
                                item.appendChild(remove);
                                supportList.appendChild(item);
                            });
                        }

                        // Each pick replaces the input's files, so add the new ones to our list.
                        supportEl.addEventListener('change', function () {
                            Array.prototype.forEach.call(supportEl.files, function (file) {
                                var exists = selectedFiles.some(function (kept) {
                                    return kept.name === file.name && kept.size === file.size;
                                });
                                if (!exists) { selectedFiles.push(file); }
                            });
                            syncFiles();
                            renderFiles();
                        });

                        // Unit of the selected leave type: day, half_day or hour.
                        function currentUnit() {
                            var option = typeEl.options[typeEl.selectedIndex];
                            return option ? option.getAttribute('data-request-unit') : 'day';
                        }

                        // Ask the server for Odoo's 'Requested (Days/Hours)' text and show it (read-only).
                        function updateDuration() {
                            var empty = currentUnit() === 'hour' ? '0:00 hours' : '0 days';
                            var single = halfEl.checked || hoursEl.checked;
                            if (!fromEl.value || (!single && !toEl.value)) {
                                daysEl.value = empty;
                                return;
                            }
                            var query = 'time_off_type=' + encodeURIComponent(typeEl.value) +
                                '&date_from=' + encodeURIComponent(fromEl.value) +
                                '&date_to=' + encodeURIComponent(toEl.value);
                            if (halfEl.checked) {
                                query += '&half_day=1&half_day_period=' + encodeURIComponent(periodEl.value);
                            }
                            if (hoursEl.checked) {
                                query += '&custom_hours=1&hour_from=' + encodeURIComponent(hourFromEl.value) +
                                    '&hour_to=' + encodeURIComponent(hourToEl.value);
                            }
                            fetch('/my/apply_time_off/days?' + query)
                                .then(function (response) { return response.json(); })
                                .then(function (data) { daysEl.value = data.display || empty; })
                                .catch(function () { daysEl.value = empty; });
                        }

                        // Show or hide Half Day / Custom Hours and their fields like the Odoo form does.
                        function refreshLayout() {
                            var unit = currentUnit();
                            unitOptions.classList.toggle('d-none', unit === 'day');
                            customHoursWrap.classList.toggle('d-none', unit !== 'hour');
                            if (unit === 'day') { halfEl.checked = false; }
                            if (unit !== 'hour') { hoursEl.checked = false; }
                            var single = halfEl.checked || hoursEl.checked;
                            periodWrap.classList.toggle('d-none', !halfEl.checked);
                            hoursWrap.classList.toggle('d-none', !hoursEl.checked);
                            toGroup.classList.toggle('d-none', single);
                            fromLabel.textContent = single ? 'Date' : 'From';
                            // Supporting Document is offered only for types that allow it.
                            var option = typeEl.options[typeEl.selectedIndex];
                            var allowsDocument = option && option.getAttribute('data-support-document') === '1';
                            supportGroup.classList.toggle('d-none', !allowsDocument);
                            if (!allowsDocument) {
                                selectedFiles = [];
                                syncFiles();
                                renderFiles();
                            }
                            updateDuration();
                        }

                        // Half Day and Custom Hours exclude each other.
                        halfEl.addEventListener('change', function () {
                            if (halfEl.checked) { hoursEl.checked = false; }
                            refreshLayout();
                        });
                        hoursEl.addEventListener('change', function () {
                            if (hoursEl.checked) { halfEl.checked = false; }
                            refreshLayout();
                        });
                        typeEl.addEventListener('change', refreshLayout);
                        [fromEl, toEl, periodEl, hourFromEl, hourToEl].forEach(function (el) {
                            el.addEventListener('change', updateDuration);
                        });
                        refreshLayout();
                    })();
